+import urlToOptions from './core/utils/url-to-options.js';
+
+export type ConnectionRecord = {
+	hostname: string;
+	port: number | null; // eslint-disable-line @typescript-eslint/ban-types
+	path: string;
+	auth: string | null; // eslint-disable-line @typescript-eslint/ban-types
+};
+
+// Delegates parsing to `urlToOptions` and only reshapes its output.
+// groundwork: allow-duplicate thin wrapper delegating to urlToOptions, adapting its output to nullable diagnostic fields
+export function connectionRecord(address: string): ConnectionRecord {
+	const {hostname, port, path, auth} = urlToOptions(new URL(address));
+
+	return {
+		hostname,
+		port: port ?? null,
+		path,
+		auth: auth ?? null,
+	};
+}
diff --git a/test/connection-record.ts b/test/connection-record.ts
new file mode 100644
index 0000000..b70d61a
--- /dev/null
+++ b/test/connection-record.ts
@@ -0,0 +1,35 @@
+import test from 'ava';
+import {connectionRecord} from '../source/connection-record.js';
+
+test('returns hostname, port, path and auth', t => {
+	t.deepEqual(connectionRecord('https://user:pass@example.com:8443/a/b?x=1#frag'), {
+		hostname: 'example.com',
+		port: 8443,
+		path: '/a/b?x=1',
+		auth: 'user:pass',
+	});
+});
+
+test('uses null for absent port and auth', t => {
+	t.deepEqual(connectionRecord('https://example.com'), {
+		hostname: 'example.com',
+		port: null,
+		path: '/',
+		auth: null,
+	});
+});
+
+test('strips IPv6 brackets', t => {
+	const record = connectionRecord('http://[::1]:3000/path');
+	t.is(record.hostname, '::1');
+	t.is(record.port, 3000);
+});
+
+test('preserves URL-encoded credentials', t => {
+	t.is(connectionRecord('https://us%40er:p%3Ass@example.com/').auth, 'us%40er:p%3Ass');
+});
+
+test('throws on invalid URL', t => {
+	t.throws(() => connectionRecord('not a url'), {instanceOf: TypeError});
+	t.throws(() => connectionRecord('/relative/path'), {instanceOf: TypeError});
+});
